### 📖 Explanation:
```
"Objects of a subclass should be replaceable with objects of the
 parent class WITHOUT breaking the program."

Simple test: If you can use Child EVERYWHERE Parent is used,
             with no surprises or errors → LSP satisfied ✅

If Child causes unexpected behaviour when substituted → LSP violated ❌
```

### 🧠 Real-World Analogy:
```
VEHICLE ANALOGY:
  You rent a car from an agency.
  You expect: 4 wheels, steering wheel, accelerator, brake.
  Every specific car model (Toyota, BMW, Maruti) substitutes for "Car".
  None of them surprises you by having the brake NOT work.

CLASSIC VIOLATION — Square extends Rectangle:
  Rectangle: width and height independent
  Square:    setting width MUST also set height (different behaviour!)
  Code that sets rect.width=5, rect.height=3 breaks if rect is a Square!
  → Square is NOT substitutable for Rectangle
```

```python name=lsp_complete.py
# ══════════════════════════════════════════════════
#  L — Liskov Substitution Principle
# ══════════════════════════════════════════════════

# ─── Classic Violation: Square IS-A Rectangle (but breaks LSP) ───
print("❌ LSP VIOLATION: Square extends Rectangle")

class Rectangle:
    def __init__(self, width, height):
        self._width  = width
        self._height = height

    @property
    def width(self):  return self._width
    @width.setter
    def width(self, w): self._width = w

    @property
    def height(self): return self._height
    @height.setter
    def height(self, h): self._height = h

    def area(self): return self._width * self._height

class Square(Rectangle):   # ❌ Conceptually true IS-A, but breaks LSP!
    def __init__(self, side):
        super().__init__(side, side)

    @Rectangle.width.setter
    def width(self, w):
        self._width = self._height = w   # must stay equal!

    @Rectangle.height.setter
    def height(self, h):
        self._width = self._height = h   # must stay equal!

def resize_and_calculate(rect: Rectangle):
    """This function works correctly for Rectangle but NOT Square!"""
    rect.width  = 5
    rect.height = 3
    expected    = 15   # 5 * 3
    actual      = rect.area()
    print(f"  Expected area: {expected}, Got: {actual} "
          f"{'✅' if actual == expected else '❌ LSP VIOLATED!'}")

r = Rectangle(4, 4)
s = Square(4)
resize_and_calculate(r)   # ✅ area = 15
resize_and_calculate(s)   # ❌ area = 9 (Square keeps width=height=3!)

# ─── Fix: Use common interface instead ───
print("\n✅ LSP FIX: Common Shape interface")
from abc import ABC, abstractmethod

class Shape(ABC):
    @property
    @abstractmethod
    def area(self) -> float: pass

    @property
    @abstractmethod
    def perimeter(self) -> float: pass

    def describe(self):
        print(f"  {self.__class__.__name__}: "
              f"area={self.area:.2f}, perimeter={self.perimeter:.2f}")

class LSP_Rectangle(Shape):
    def __init__(self, width, height):
        self.width  = width
        self.height = height

    @property
    def area(self): return self.width * self.height

    @property
    def perimeter(self): return 2 * (self.width + self.height)

class LSP_Square(Shape):
    def __init__(self, side):
        self.side = side

    @property
    def area(self): return self.side ** 2

    @property
    def perimeter(self): return 4 * self.side

def print_shape_info(shape: Shape):
    """Works correctly for ANY Shape — LSP satisfied!"""
    shape.describe()

shapes = [LSP_Rectangle(5,3), LSP_Square(4), LSP_Rectangle(10,2)]
for s in shapes:
    print_shape_info(s)  # ✅ each substitutes for Shape perfectly!

# ─── Real-World: Payment Gateway LSP ───
print("\n=== LSP in Payment Gateways ===")

class PaymentGateway(ABC):
    @abstractmethod
    def charge(self, amount: float, card_token: str) -> dict: pass

    @abstractmethod
    def refund(self, transaction_id: str, amount: float) -> dict: pass

    def process_order(self, amount: float, card_token: str) -> str:
        """Template method — calls charge(). Must work with ANY subclass."""
        result = self.charge(amount, card_token)
        if result['success']:
            return result['transaction_id']
        raise RuntimeError(f"Payment failed: {result.get('error')}")

class RazorpayGateway(PaymentGateway):
    def charge(self, amount, card_token):
        print(f"  💳 Razorpay: charging ₹{amount}")
        return {"success": True, "transaction_id": f"rzp_{id(self)}"}

    def refund(self, txn_id, amount):
        print(f"  💳 Razorpay: refunding ₹{amount} for {txn_id}")
        return {"success": True}

class StripeGateway(PaymentGateway):
    def charge(self, amount, card_token):
        print(f"  💳 Stripe: charging ₹{amount}")
        return {"success": True, "transaction_id": f"ch_{id(self)}"}

    def refund(self, txn_id, amount):
        print(f"  💳 Stripe: refunding ₹{amount} for {txn_id}")
        return {"success": True}

class MockGateway(PaymentGateway):
    """For testing — substitutes perfectly!"""
    def charge(self, amount, card_token):
        return {"success": True, "transaction_id": "test_123"}

    def refund(self, txn_id, amount):
        return {"success": True}

# Same process_order() call works for ALL gateways — LSP satisfied!
for gateway in [RazorpayGateway(), StripeGateway(), MockGateway()]:
    txn = gateway.process_order(1500.0, "tok_test")
    print(f"  ✅ TXN: {txn}")
```

### 📖 Explanation:
```
"Clients should not be forced to depend on interfaces they don't use."

Don't create FAT interfaces that force implementors to implement
methods they don't need.
Create SMALL, FOCUSED interfaces instead.

FAT interface:
  class Animal:
    fly(), swim(), walk(), burrow(), climb()  ← Dog can't fly!

THIN interfaces:
  class Flyable:  fly()
  class Swimmable: swim()
  class Walkable: walk()

  Dog(Walkable, Swimmable)
  Eagle(Flyable, Walkable)
  Fish(Swimmable)
```

### 🧠 Real-World Analogy:
```
REMOTE CONTROL ANALOGY:
  A TV remote has: Power, Volume, Channel buttons.
  An AC remote has: Power, Temperature, Fan speed buttons.
  A DVD remote has: Power, Play, Pause, Rewind buttons.

  Bad design: ONE super-remote with ALL 20 buttons for every device.
              Each device "interface" forces you to have useless buttons.

  Good design: Each device has its own focused remote interface.
               Only buttons relevant to THAT device.
```

```python name=isp_complete.py
# ══════════════════════════════════════════════════
#  I — Interface Segregation Principle
# ══════════════════════════════════════════════════
from abc import ABC, abstractmethod

# ─── ❌ VIOLATION: Fat interface forces empty implementations ───
class Worker_FAT(ABC):
    @abstractmethod
    def work(self): pass

    @abstractmethod
    def eat(self): pass      # Robots don't eat!

    @abstractmethod
    def sleep(self): pass    # Robots don't sleep!

    @abstractmethod
    def attend_meeting(self): pass  # Factory workers don't have meetings!

class HumanWorker(Worker_FAT):
    def work(self):           print("  👷 Human working")
    def eat(self):            print("  🍱 Human eating")
    def sleep(self):          print("  😴 Human sleeping")
    def attend_meeting(self): print("  📅 Human in meeting")

class RobotWorker_BAD(Worker_FAT):
    def work(self):           print("  🤖 Robot working")
    def eat(self):            raise NotImplementedError("Robots don't eat!")  # ❌
    def sleep(self):          raise NotImplementedError("Robots don't sleep!")  # ❌
    def attend_meeting(self): raise NotImplementedError("Robots don't attend!")  # ❌

# ─── ✅ CORRECT: Segregated thin interfaces ───
print("✅ ISP: Segregated interfaces")

class Workable(ABC):
    @abstractmethod
    def work(self) -> None: pass

class Eatable(ABC):
    @abstractmethod
    def eat(self, meal: str) -> None: pass

class Sleepable(ABC):
    @abstractmethod
    def sleep(self, hours: int) -> None: pass

class Meetable(ABC):
    @abstractmethod
    def attend_meeting(self, topic: str) -> None: pass

class Rechargeable(ABC):
    @abstractmethod
    def recharge(self, minutes: int) -> None: pass

# Each class implements ONLY what it needs!
class HumanEmployee(Workable, Eatable, Sleepable, Meetable):
    def __init__(self, name):
        self.name = name

    def work(self):
        print(f"  👷 {self.name} is working")

    def eat(self, meal):
        print(f"  🍱 {self.name} is eating {meal}")

    def sleep(self, hours):
        print(f"  😴 {self.name} is sleeping {hours} hours")

    def attend_meeting(self, topic):
        print(f"  📅 {self.name} attending meeting: {topic}")

class Robot(Workable, Rechargeable):
    """Robot only implements what it NEEDS — no forced empty methods!"""
    def __init__(self, model):
        self.model = model

    def work(self):
        print(f"  🤖 Robot {self.model} is working")

    def recharge(self, minutes):
        print(f"  ⚡ Robot {self.model} recharging for {minutes} min")

class PartTimeContractor(Workable, Eatable):
    """Part-timer works and eats but no meetings/sleep tracking"""
    def __init__(self, name):
        self.name = name

    def work(self):
        print(f"  💼 Contractor {self.name} working")

    def eat(self, meal):
        print(f"  🍕 Contractor {self.name} eating {meal}")

# Functions that accept ONLY the interface they need
def assign_work(worker: Workable):
    worker.work()

def schedule_meal(entity: Eatable, meal: str):
    entity.eat(meal)

def schedule_meeting(attendee: Meetable, topic: str):
    attendee.attend_meeting(topic)

def recharge_robot(robot: Rechargeable, mins: int):
    robot.recharge(mins)

print("\n--- Human Employee ---")
alice = HumanEmployee("Alice")
assign_work(alice)
schedule_meal(alice, "Biryani")
schedule_meeting(alice, "Q2 Planning")

print("\n--- Robot ---")
robot = Robot("R2-D2")
assign_work(robot)
recharge_robot(robot, 30)
# schedule_meal(robot, "Oil")  # ❌ Type error — Robot is not Eatable! Good!

print("\n--- Contractor ---")
bob = PartTimeContractor("Bob")
assign_work(bob)
schedule_meal(bob, "Pizza")
# schedule_meeting(bob, "Standup")  # ❌ Bob is not Meetable!

# ─── Real-World: File I/O ISP ───
print("\n=== ISP in File Operations ===")

class FileReader(ABC):
    @abstractmethod
    def read(self) -> str: pass

class FileWriter(ABC):
    @abstractmethod
    def write(self, data: str) -> bool: pass

class FileSeeker(ABC):
    @abstractmethod
    def seek(self, pos: int) -> None: pass

class FileCloser(ABC):
    @abstractmethod
    def close(self) -> None: pass

class ReadOnlyFile(FileReader, FileCloser):
    """Only read operations — no write!"""
    def __init__(self, path):
        self.path = path
    def read(self): return f"[Contents of {self.path}]"
    def close(self): print(f"  📁 Closed {self.path}")

class AppendOnlyLog(FileWriter, FileCloser):
    """Only append — no reading/seeking"""
    def __init__(self, path):
        self.path = path
    def write(self, data): print(f"  📝 Appending to {self.path}: {data}")
    def close(self): print(f"  📁 Log closed")

class FullAccessFile(FileReader, FileWriter, FileSeeker, FileCloser):
    def __init__(self, path):
        self.path = path
        self._pos = 0
    def read(self):   return f"[Read from {self.path}]"
    def write(self, d): print(f"  📝 Writing to {self.path}: {d}")
    def seek(self, p):  self._pos = p
    def close(self):    print(f"  📁 Full file closed")

def backup_data(source: FileReader, dest: FileWriter):
    """Only needs read + write interfaces — doesn't care about seek/close"""
    data = source.read()
    dest.write(data)
    print("  ✅ Backup complete")

src  = ReadOnlyFile("source.dat")
dest = AppendOnlyLog("backup.log")
backup_data(src, dest)
```
